Lemma rdn_same_byte : forall (n : nat) (M M' : word -> option byte) a a' bs (k : nat),
  rdn segs M (Z_to_bv 64 a) n = Some bs -> rdn segs M' (Z_to_bv 64 a') n = Some bs -> (k < n)%nat ->
  rdn segs M (Z_to_bv 64 (a + Z.of_nat k)) 1 = rdn segs M' (Z_to_bv 64 (a' + Z.of_nat k)) 1.
