(* [comment removed for export] *)
Lemma copy_run_c (pc : Z) (CPY : PMCP.copy1_spec segs pc) (fx : FPState) R M (dst src n r : Z) :
  getr R (L5K.reg 10) = Z_to_bv 64 dst -> getr R (L5K.reg 11) = Z_to_bv 64 src -> getr R (L5K.reg 12) = Z_to_bv 64 n ->
  getr R (L5K.reg 1) = Z_to_bv 64 r -> L5.ra_ok r ->
  1 <= n -> 0 <= dst -> dst + n < 2 ^ 63 -> 0 <= src -> src + n < 2 ^ 63 -> (dst + n <= src \/ src + n <= dst) ->
  L5.writable segs M dst n -> L5.defined M src n ->
  exists R3 M3, msteps segs (@mkst fx R (Z_to_bv 64 pc) M (seg_rom segs)) (@mkst fx R3 (Z_to_bv 64 r) M3 (seg_rom segs))
    /\ mem_grows M M3
    /\ (forall a, 0 <= a < 2 ^ 64 -> ~ (dst <= a < dst + n) -> M3 (Z_to_bv 64 a) = M (Z_to_bv 64 a))
    /\ L5.defined M3 dst n
    /\ (forall i, 0 <= i < n -> M3 (Z_to_bv 64 (dst + i)) = M (Z_to_bv 64 (src + i)))
    /\ (forall i, In i L5K.CS -> getr R3 (L5K.reg i) = getr R (L5K.reg i)) /\ getr R3 (L5K.reg 10) = Z_to_bv 64 dst.
Proof.
